class InventoryServiceV1 {
  subscribers: ((item:any)=>void)[] = []
  addItem(item:any){ this.subscribers.forEach(s => s(item)) }
}

class InventoryServiceV2 {
  private emitter = new EventEmitter()
  addItem(item:any){ this.emitter.emit('itemAdded', item) }
}

