class ReportGeneratorA {
  constructor(private storage: Storage, private notifier: Notifier) {}
  generate(){ const data = this.storage.load(); this.notifier.notify(data) }
}

// Version B
class ReportGeneratorB {
  generate(){
    const storage = ServiceRegistry.get('storage') as Storage
    const notifier = ServiceRegistry.get('notifier') as Notifier
    const data = storage.load()
    notifier.notify(data)
  }
}
